import { SpecDefinition } from '../../types';
import { WorkspaceFileManager } from '../sandbox/fileManager';
import { customEndpointGroups } from '../spec/specSchema';
import { customRoutePath } from './backendAgent';
import { pagePath, agentPages } from './frontendAgent';
import { customTestPath } from './testerAgent';

export const SEED_DATA_PATH = 'prisma/seed.data.js';

/** Files written by agents. Everything else in the workspace is generated by the platform and must not be edited by a model. */
export function ownedPaths(spec: SpecDefinition): string[] {
  return [
    ...Array.from(customEndpointGroups(spec).keys()).flatMap((segment) => [customRoutePath(segment), customTestPath(segment)]),
    ...agentPages(spec).map(pagePath),
    SEED_DATA_PATH,
  ];
}

export async function listOwnedFiles(spec: SpecDefinition, fm: WorkspaceFileManager): Promise<string[]> {
  const present = ownedPaths(spec).filter((p) => fm.fileExists(p));
  const extraTests = (await fm.listFiles('tests/custom')).filter((p) => !present.includes(p));
  return [...present, ...extraTests];
}

export function isFrontendFile(relPath: string): boolean {
  return relPath.startsWith('public/');
}

export function isOwnedPath(spec: SpecDefinition, relPath: string): boolean {
  return ownedPaths(spec).includes(relPath) || /^tests\/custom\/[\w.-]+\.test\.js$/.test(relPath);
}
